source(file.path(commandArgs(TRUE)[1],'code/common.R'));suppressPackageStartupMessages(library(Banksy));source(file.path(root,'code/fast_singletons.R'));assignInNamespace('GroupSingletons',fast_group_singletons,ns='Seurat');if(all(file.exists(file.path(out,paste0(c('l00','l02','l08'),'_complete.json')))))quit(save='no');q<-readRDS(file.path(out,'tmp/hvg_input.rds'));knn<-readRDS(file.path(out,'tmp/knn.rds'));ids<-colnames(q);co<-fread(file.path(out,'coordinates.tsv.gz'));stopifnot(identical(ids,co$bin_id));versions<-list(R=R.version.string,Banksy=as.character(packageVersion('Banksy')),Seurat=as.character(packageVersion('Seurat')),SeuratObject=as.character(packageVersion('SeuratObject')),Banksy_path=find.package('Banksy'),interface='Banksy:::.banksy_lazy_pca_core; same core as current official SeuratWrappers lazy path',pca_backend='cpp',singleton_rule='cached Seurat 5.5.1 exact sequential rule; native-equivalence test passed',use_agf=FALSE,scale_max=10,split_scale=FALSE);write_json(versions,file.path(out,'model_versions.json'),auto_unbox=TRUE,pretty=TRUE)
for(tag in c('l00','l02','l08')){f<-file.path(out,paste0(tag,'_embeddings.rds'));done<-file.path(out,paste0(tag,'_complete.json'));if(file.exists(done))next;lam<-c(l00=0,l02=.2,l08=.8)[[tag]];set.seed(123);cat('MODEL_START',s,tag,format(Sys.time()),'\n');pcfile<-file.path(out,'tmp',paste0(tag,'_pca.rds'));if(file.exists(pcfile))pca<-readRDS(pcfile) else {pca<-Banksy:::.banksy_lazy_pca_core(q,knn_list=list(knn),lambda=lam,npcs=30L,split_scale=FALSE,scale_max=10,seed=123,pca_backend='cpp',verbose=TRUE);saveRDS(pca,pcfile,compress=FALSE)};emb<-pca$embeddings;stopifnot(identical(rownames(emb),ids),ncol(emb)==30,all(is.finite(emb)));clusterfile<-file.path(out,paste0(tag,'_clusters.tsv.gz'));if(file.exists(clusterfile)){zz<-fread(clusterfile);stopifnot(identical(zz$bin_id,ids));cluster<-as.character(zz$cluster)} else {set.seed(123);nn<-FindNeighbors(emb,k.param=20,compute.SNN=TRUE,nn.method='annoy',annoy.metric='euclidean',n.trees=50,prune.SNN=1/15,verbose=TRUE);cl<-FindClusters(nn$snn,algorithm=1,resolution=.5,random.seed=123,n.start=10,n.iter=10,verbose=TRUE);stopifnot(identical(rownames(cl),ids));cluster<-as.character(cl[[1]]);names(cluster)<-ids;fwrite(data.table(bin_id=ids,cluster=cluster),file.path(out,paste0(tag,'_clusters.tsv.gz')),sep='\t');rm(nn,cl);gc()};future::plan(future::multicore,workers=8);u<-RunUMAP(emb,umap.method='uwot',n.neighbors=30,n.components=2,metric='cosine',n.epochs=200,min.dist=.3,spread=1,seed.use=123,assay='RNA',verbose=TRUE);future::plan('sequential');if(inherits(u,'DimReduc'))u<-Embeddings(u);stopifnot(identical(rownames(u),ids),all(is.finite(u)));saveRDS(list(pca=emb,umap=u,loadings=pca$loadings,stdev=pca$stdev,total_variance=pca$total_var,lambda=lam,seed=123),f,compress='gzip');write_json(list(section=s,lambda=lam,n=length(ids),clusters=length(unique(cluster)),npcs=30,all_bins_direct=TRUE,normalization='existing RNA LogNormalize10000',HVG=3000,scale_max=10,use_agf=FALSE,split_scale=FALSE,graph_name=paste0('banksy_',tag,'_snn'),cluster_co